  backToForm: ja.errors.exportShared.backToForm,
  retry: ja.errors.exportFailed.actions.retry,
  specifyMusescore: ja.errors.musescoreMissing.actions.specifyMusescore,
  diagnostics: ja.errors.engineUnavailable.actions.diagnostics,
};

/** §20 何が保持されているか — the staging guarantee (#258) means a
 *  pre-commit failure leaves the destination untouched; a commit
 *  failure may leave a partial set. Unknown-phase failures make no
 *  claim at all. */
const ERROR_KEPT: Partial<Record<ErrorKind, string>> = {
  permission: ja.errors.exportShared.kept,
  unavailable: ja.errors.exportShared.kept,
  musescore: ja.errors.exportShared.kept,
  renderFailed: ja.errors.exportShared.kept,
  diskFull: ja.errors.exportShared.kept,
  destinationInvalid: ja.errors.exportShared.kept,
  sourceMissing: ja.errors.exportShared.kept,
  writeFailed: ja.errors.exportShared.kept,
  internal: ja.errors.exportShared.kept,
  nameExhausted: ja.errors.exportShared.kept,
  commitFailed: ja.errors.exportShared.keptPartial,
};

/**
 * 書き出し dialog (GUI_UX_SPEC §17, §20; issue UI-060).
 *
 * Formats (all checked by default):
 *   楽譜: コンサートピッチ / F管ホルン MusicXML
 *   PDF:  コンサートピッチ / F管ホルン PDF  — disabled when MuseScore is
 *         missing, with the spec'd note + 場所を指定 recovery; MusicXML and
 *         MIDI stay available (acceptance: "missing MuseScore does not
 *         block other formats").
 *   MIDI: 再生用MIDI（実音） — sounding pitch only (ENG-001).
 *
 * Phases: loading → form → running → done | error. Errors keep the §20
 * shape (何が失敗したか → 影響 → 次にできること) and never render engine
 * output — only stable ExportError codes map to Japanese recovery copy.
 */
export function ExportDialog({
  open,
  onOpenChange,
  port,
  defaultDestination,
  toolOverrides,
  onOpenSettings,
  onOpenDiagnostics,
  onAnnounce,
  initialSelected,
  onSelectionChange,
  suggestedBasename,
}: {
  open: boolean;
  onOpenChange(open: boolean): void;
  port: ExportPort;
  /** 設定 → 書き出し → 既定の保存先 ("" = ask the port). */
  defaultDestination: string;
  /** 設定 → ツール user paths — non-empty paths override probing. */
  toolOverrides?: ToolPathOverrides;
  /** Recovery: opens 設定 focused on the 書き出し category. */
  onOpenSettings(category: "export"): void;
  onOpenDiagnostics(): void;
  onAnnounce(message: string): void;
  /** #377: the last-used format set from settings. */
  initialSelected: Record<ExportFormatId, boolean>;
  /** #377: persist the user's picks so the next open restores them. */
  onSelectionChange?(selected: Record<ExportFormatId, boolean>): void;
  /** #362: suggested file basename — score title when edited, else
   *  the source-audio stem. Editable in the dialog. */
  suggestedBasename: string;
}) {
  const [phase, setPhase] = useState<Phase>("loading");
  const [caps, setCaps] = useState<ExportCapabilities | null>(null);
  const [destination, setDestination] = useState("");
  // #377: the last-used set comes from settings — reopening the dialog
  // keeps the user's formats instead of resetting all six every time.
  const [selected, setSelected] = useState<Record<ExportFormatId, boolean>>(
    initialSelected,
  );
  // #362: the artifact basename is user-editable — seeded from the
  // score title / source stem each open, not silently fixed.
  const [basename, setBasename] = useState("");
  const [result, setResult] = useState<ExportResult | null>(null);
  const [errorKind, setErrorKind] = useState<ErrorKind>("failed");
  // #231: pending collision prompt — the port's onCollision awaits
  // this resolver while the dialog shows overwrite/rename/cancel.
  const [collision, setCollision] = useState<{
    names: readonly string[];
    resolve: (policy: "overwrite" | "rename" | "cancel") => void;
  } | null>(null);
  // Stale-response guard: a probe/export finishing after close or a newer
  // attempt must not overwrite the current phase.
  const generation = useRef(0);
  // #383: the running export's abort handle — cancel means cancel, so
  // closing (button or X/Esc) flips this instead of hiding live work.
  const abortRef = useRef<AbortController | null>(null);

  const e = ja.exportSheet;

  // Probe capabilities + destination when the dialog opens.
  useEffect(() => {
    if (!open) return;
    const gen = ++generation.current;
    setPhase("loading");
    setCaps(null);
    setResult(null);
    // #362: reseed the basename per open — the score title may have
    // been edited since the last export.
    setBasename(suggestedBasename);
    let cancelled = false;
    void (async () => {
      try {
        const [capabilities, fallbackDir] = await Promise.all([
          port.capabilities(toolOverrides),
          defaultDestination
            ? Promise.resolve(defaultDestination)
            : port.defaultDestination(),
        ]);
        if (cancelled || generation.current !== gen) return;
        setCaps(capabilities);
        setDestination(defaultDestination || fallbackDir);
        setPhase("form");
      } catch (err) {
        if (cancelled || generation.current !== gen) return;
        // #384: probe failures land on the matching surface too — a
        // permission-denied probe result offers destination advice,
        // not just the engine-down page.
        setErrorKind(KIND_BY_CODE[exportErrorCode(err)]);
        setPhase("error");
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [open, port, defaultDestination, toolOverrides, suggestedBasename]);

  const close = useCallback(() => {
    if (phase === "running") {
      // A running export aborts for real — the rejection lands the
      // dialog back on the form; nothing here closes over live work.
      abortRef.current?.abort();
      return;
    }
    if (phase === "collision") {
      // Same user semantics as the running cancel: the pending
      // prompt resolves as cancelled, the export rejects, and the
      // dialog lands back on the form — not a closed window over an
      // aborted write (#383).
      collision?.resolve("cancel");
      setCollision(null);
      return;
    }
    generation.current += 1;
    // #231: a pending collision prompt must not keep the export
    // promise alive past close — resolve it as cancelled.
    collision?.resolve("cancel");
    setCollision(null);
    onOpenChange(false);
  }, [onOpenChange, collision, phase]);

  // #231: the collision prompt's three policies — overwrite keeps
  // the planned names, rename re-stems the set to <basename>_N,
  // cancel aborts (the port surfaces EXPORT_CANCELLED → form).
  const resolveCollision = useCallback(
    (policy: "overwrite" | "rename" | "cancel") => {
      const pending = collision;
      setCollision(null);
      if (policy === "cancel") {
        pending?.resolve("cancel");
        return;
      }
      setPhase("running");
      pending?.resolve(policy);
    },
    [collision],
  );

  const blocked = caps ? pdfBlocked(caps) : false;
  // #87: the audio bundle needs a real path — browser-held bytes and
  // pathless recordings keep the checkbox off with an honest tooltip.
  const audioBlocked = caps != null && !caps.audioAvailable;
  const running = phase === "running";
  // Formats that will actually export — checked AND not blocked.
  // anyChecked alone let submit run with an empty list when every
  // checked format was blocked (e.g. PDF-only selection + no MuseScore).
  const effectiveFormats = (
    Object.keys(selected) as ExportFormatId[]
  ).filter(
    (f) =>
      selected[f] &&
      !(blocked && EXPORT_FORMAT_GROUPS[f] === "pdf") &&
      !(audioBlocked && f === "sourceAudio"),
  );

  const submit = useCallback(async () => {
    const gen = ++generation.current;
    setPhase("running");
    // #383: every attempt gets a fresh controller — the cancel
    // button and dialog-close both flip it.
    const controller = new AbortController();
    abortRef.current = controller;
    try {
      const res = await port.export({
        formats: effectiveFormats,
        destination,
        // #362: the edited basename wins over the source stem —
        // sanitized/emptied upstream in the port.
        basename: basename.trim() || undefined,
        // #231: existing artifact names pause the export here — the
        // dialog shows one prompt for the whole set and the chosen
        // policy resumes (or cancels) the transactional write.
        onCollision: (names) =>
          new Promise<"overwrite" | "rename" | "cancel">((resolve) => {
            if (generation.current !== gen) {
              resolve("cancel");
              return;
            }
            setCollision({ names, resolve });
            setPhase("collision");
          }),
      }, controller.signal);
      if (generation.current !== gen) return;
      setResult(res);
      setPhase("done");
      onAnnounce(ja.notifications.exportDone);
    } catch (err) {
      if (generation.current !== gen) return;
      const code = exportErrorCode(err);
      if (code === "EXPORT_CANCELLED") {
        // #231: the user cancelled at the collision prompt — back to
        // the form quietly, not an error surface.
        setPhase("form");
        return;
      }
      setErrorKind(KIND_BY_CODE[code]);
      setPhase("error");
    } finally {
      abortRef.current = null;
    }
  }, [effectiveFormats, port, destination, basename, onAnnounce]);

  const pickDestination = useCallback(async () => {
    try {
      const dir = await port.chooseDestination(destination);
      if (dir) setDestination(dir);
    } catch {
      /* unsupported picker — the path row stays editable nowhere else,
         so surface the honest failure instead of dying silently */
      onAnnounce(ja.exportSheet.destinationPickFailed);
    }
  }, [port, destination, onAnnounce]);

  const reveal = useCallback(async () => {
    const dir = result?.destination ?? destination;
    const ok = await port.revealInExplorer(dir).catch(() => false);
    if (!ok) onAnnounce(ja.exportSheet.revealFailed);
  }, [port, result, destination, onAnnounce]);

  const goToMuseScoreSettings = useCallback(() => {
    close();
    onOpenSettings("export");
  }, [close, onOpenSettings]);

  const toggle =
    (key: ExportFormatId) =>
    (_: unknown, d: { checked: boolean | "mixed" }) =>
      setSelected((s) => ({ ...s, [key]: d.checked === true }));

  // #377: persist the last-used set — the next open restores it.
  // Fires once on mount with the seeded value too; the write is
  // idempotent so that echo is harmless.
  useEffect(() => {
    onSelectionChange?.(selected);
  }, [selected, onSelectionChange]);

  const title =
    phase === "done"
      ? e.completeTitle
      : phase === "error"
        ? ERROR_TITLE[errorKind]
        : phase === "collision"
          ? e.collisionTitle
        : e.title;

  const formatRow = (id: ExportFormatId) => {
    const pdfOff = blocked && EXPORT_FORMAT_GROUPS[id] === "pdf";
    const audioOff = audioBlocked && id === "sourceAudio";
    const disabled = running || pdfOff || audioOff;
    const checkbox = (
      <Checkbox
        checked={selected[id]}
        onChange={toggle(id)}
        label={e.options[id]}
        disabled={disabled}
      />
    );
    // Disabled checkboxes can't announce *why* — the spec'd tooltip does.
    if (audioOff) {
      return (
        <Tooltip
          key={id}
          content={e.audioDisabledTooltip}
          relationship="label"
        >
          <span className="hs-export__option">{checkbox}</span>
        </Tooltip>
      );
    }
    return pdfOff ? (
      <Tooltip
        key={id}
        content={e.pdfDisabledTooltip}
        relationship="label"
      >
        <span className="hs-export__option">{checkbox}</span>
      </Tooltip>
    ) : (
      <span key={id} className="hs-export__option">
        {checkbox}
      </span>
    );
  };

  return (
    <HsDialog
      open={open}
      onOpenChange={(o) => (o ? onOpenChange(true) : close())}
      title={title}
      actions={
        phase === "form" || running ? (
          <>
            <HsButton onClick={close}>{ja.common.cancel}</HsButton>
            <HsButton
              variant="primary"
              disabled={effectiveFormats.length === 0 || running || !destination}
              loading={running}
              onClick={() => void submit()}
            >
              {running ? e.running : e.submit}
            </HsButton>
          </>
        ) : phase === "collision" ? (
          <>
            <HsButton onClick={() => resolveCollision("cancel")}>
              {ja.common.cancel}
            </HsButton>
            <HsButton
              variant="secondary"
              onClick={() => resolveCollision("rename")}
            >
              {e.collisionRename}
            </HsButton>
            <HsButton
              variant="primary"
              onClick={() => resolveCollision("overwrite")}
            >
              {e.collisionOverwrite}
            </HsButton>
          </>
        ) : phase === "done" ? (
          <>
            <HsButton onClick={() => void reveal()}>
              {e.revealInExplorer}
            </HsButton>
            <HsButton variant="primary" onClick={close}>
              {ja.common.close}
            </HsButton>
          </>
        ) : phase === "error" ? (
          <>
            {ERROR_ACTIONS[errorKind].map((action, i) => {
              const variant = i === 0 ? "primary" : undefined;
              switch (action) {
                case "chooseDestination":
                case "backToForm":
                  // Both land on the form — destination picker,
                  // basename field and the 音源同梱 checkbox all live
                  // there; the label names the relevant fix.
                  return (
                    <HsButton
                      key={action}
                      variant={variant}
                      onClick={() => setPhase("form")}
                    >
                      {ERROR_ACTION_LABEL[action]}
                    </HsButton>
                  );
                case "retry":
                  return (
                    <HsButton
                      key={action}
                      variant={variant}
                      onClick={() => void submit()}
                    >
                      {ERROR_ACTION_LABEL[action]}
                    </HsButton>
                  );
                case "specifyMusescore":
                  return (
                    <HsButton
                      key={action}
                      variant={variant}
                      onClick={goToMuseScoreSettings}
                    >
                      {ERROR_ACTION_LABEL[action]}
                    </HsButton>
                  );
                case "diagnostics":
                  return (
                    <HsButton
                      key={action}
                      variant={variant}
                      onClick={() => {
                        close();
                        onOpenDiagnostics();
                      }}
                    >
                      {ERROR_ACTION_LABEL[action]}
                    </HsButton>
                  );
              }
            })}
            <HsButton onClick={close}>{ja.common.close}</HsButton>
          </>
        ) : undefined
      }
    >
      {phase === "loading" ? (
        <HsProgress label={e.loading} />
      ) : phase === "form" || running ? (
        <div className="hs-export">
          <h3 className="hs-export__section">{e.scoreSection}</h3>
          <div className="hs-export__group">
            {formatRow("concertMusicxml")}
            {formatRow("hornMusicxml")}
          </div>

          <h3 className="hs-export__section">{e.pdfSection}</h3>
          <div className="hs-export__group">
            {formatRow("concertPdf")}
            {formatRow("hornPdf")}
          </div>
          {blocked ? (
            <p className="hs-export__note" role="note">
              <Warning24Regular aria-hidden="true" />
              <span>{e.museScoreMissingNote}</span>
              <HsButton
                variant="subtle"
                size="small"
                onClick={goToMuseScoreSettings}
              >
                {e.specifyMuseScore}
              </HsButton>
            </p>
          ) : null}

          <h3 className="hs-export__section">{e.midiSection}</h3>
          <div className="hs-export__group">{formatRow("playbackMidi")}</div>

          <h3 className="hs-export__section">{e.audioSection}</h3>
          <div className="hs-export__group">{formatRow("sourceAudio")}</div>

          {/* #362: the artifact basename is user-editable — the
              score title (or source stem) seeds it, and the field
              feeds <basename>_<artifact> naming. */}
          <div className="hs-export__basename">
            <label
              className="hs-export__basename-label"
              htmlFor="hs-export-basename"
            >
              {e.fileName}
            </label>
            <Input
              id="hs-export-basename"
              value={basename}
              disabled={running}
              onChange={(_e, d) => setBasename(d.value)}
            />
            <span className="hs-export__basename-hint">
              {e.fileNameHint}
            </span>
          </div>

          <div className="hs-export__dest">
            <span className="hs-export__dest-label">{e.destination}</span>
            <span className="hs-export__dest-path" title={destination}>
              {destination}
            </span>
            <HsButton
              variant="secondary"
              size="small"
              disabled={running}
              onClick={() => void pickDestination()}
            >
              {ja.common.browse}
            </HsButton>
          </div>

          {running ? (
            <HsProgress label={e.running} className="hs-export__progress" />
          ) : null}
        </div>
      ) : phase === "collision" ? (
        <div className="hs-export">
          <p className="hs-export__error">
            <Warning24Regular
              aria-hidden="true"
              className="hs-export__error-icon"
            />
            <span>{e.collisionBody}</span>
          </p>
          <ul className="hs-export__files">
            {collision?.names.map((n) => <li key={n}>{n}</li>)}
          </ul>
        </div>
      ) : phase === "done" ? (
        <div className="hs-export">
          <p className="hs-export__done">
            <CheckmarkCircle24Regular
              aria-hidden="true"
              className="hs-export__done-icon"
            />
            <span>
              {e.completeCount.replace(
                "{count}",
                String(result?.files.length ?? 0),
              )}
            </span>
          </p>
          <ul className="hs-export__files">
            {result?.files.map((f) => (
              <li key={f.format} title={f.path}>
                {f.name}
              </li>
            ))}
          </ul>
        </div>
      ) : (
        <div className="hs-export">
          <p className="hs-export__error">
            <ErrorCircle24Regular
              aria-hidden="true"
              className="hs-export__error-icon"
            />
            <span>{ERROR_BODY[errorKind]}</span>
          </p>
          {ERROR_KEPT[errorKind] ? (
            <p className="hs-export__note" role="note">
              <span>{ERROR_KEPT[errorKind]}</span>
            </p>
          ) : null}
        </div>
      )}
    </HsDialog>
  );
}

/**
 * ExportPort contract tests (UI-060) — run against MockExportPort, the
 * same in-process fake the dialog uses in `vite dev`. The port boundary
 * is what a real engine implements later, so the mock's behaviour is the
 * contract: ENG-001 artifact names, typed ExportError codes (never raw
 * engine output), and honest capability gating.
 */

import { describe, expect, it } from "vitest";
import { MockExportPort } from "./mockPort";
import {
  ExportError,
  EXPORT_FORMAT_IDS,
  exportErrorCode,
  pdfBlocked,
  type ExportPort,
} from "./types";

function port(options?: ConstructorParameters<typeof MockExportPort>[0]) {
  return new MockExportPort({ latencyMs: 0, ...options });
}

describe("MockExportPort.export", () => {
  it("writes only the requested formats with ENG-001 artifact names", async () => {
    const res = await port().export({
      formats: ["hornMusicxml", "playbackMidi"],
      destination: "C:\\out",
      basename: "take1",
    });
    expect(res.destination).toBe("C:\\out");
    expect(res.files.map((f) => f.name)).toEqual([
      "take1_horn_in_f.musicxml",
      "take1_playback.mid",
    ]);
    expect(res.files.map((f) => f.path)).toEqual([
      "C:\\out\\take1_horn_in_f.musicxml",
      "C:\\out\\take1_playback.mid",
    ]);
  });

  it("keeps the canonical format order regardless of selection order", async () => {
    const res = await port().export({
      formats: [...EXPORT_FORMAT_IDS].reverse(),
      destination: "D:\\",
    });
    expect(res.files.map((f) => f.format)).toEqual(EXPORT_FORMAT_IDS);
  });

  it("bundles the source audio as <basename>_source.wav (#87)", async () => {
    const res = await port().export({
      formats: ["sourceAudio"],
      destination: "C:\\out",
      basename: "take1",
    });
    expect(res.files).toEqual([
      {
        format: "sourceAudio",
        name: "take1_source.wav",
        path: "C:\\out\\take1_source.wav",
      },
    ]);
  });

  it("rejects with a typed ExportError when nothing is selected", async () => {
    await expect(
      port().export({ formats: [], destination: "C:\\out" }),
    ).rejects.toMatchObject({ name: "ExportError", code: "EXPORT_FAILED" });
  });

  it("maps every injected failure to its stable code", async () => {
    for (const code of [
      "PERMISSION_DENIED",
      "ENGINE_UNAVAILABLE",
      "MUSESCORE_UNAVAILABLE",
      "EXPORT_DISK_FULL",
      "EXPORT_SOURCE_MISSING",
      "EXPORT_MUSESCORE_RENDER_FAILED",
      "EXPORT_DESTINATION_INVALID",
      "EXPORT_WRITE_FAILED",
      "EXPORT_COMMIT_FAILED",
      "EXPORT_NAME_INVALID",
      "EXPORT_NAME_EXHAUSTED",
      "EXPORT_INTERNAL",
      "EXPORT_FAILED",
    ] as const) {
      const err = await port({ failure: code })
        .export({ formats: ["playbackMidi"], destination: "C:\\out" })
        .catch((e: unknown) => e);
      expect(err).toBeInstanceOf(ExportError);
      expect(exportErrorCode(err)).toBe(code);
    }
  });
});

describe("capabilities + pdf gate", () => {
  it("reports MuseScore found by default so PDF stays enabled", async () => {
    const caps = await port().capabilities();
    expect(caps.museScore.status).toBe("found");
    expect(pdfBlocked(caps)).toBe(false);
  });

  it("MuseScore missing blocks PDF only — other formats stay available", async () => {
    const caps = await port({ museScore: { status: "missing" } }).capabilities();
    expect(pdfBlocked(caps)).toBe(true);
    // The dialog's own filtering keeps score/midi formats enabled; the
    // gate never touches them.
    expect(caps.ffmpeg.status).toBe("found");
  });

  it("user-specified tool paths override probing (設定 → ツール)", async () => {
    const caps = await port({ museScore: { status: "missing" } }).capabilities({
      museScorePath: "D:\\MuseScore\\MuseScore4.exe",
    });
    expect(caps.museScore).toMatchObject({
      status: "found",
      path: "D:\\MuseScore\\MuseScore4.exe",
    });
    expect(pdfBlocked(caps)).toBe(false);
  });

  it("audioAvailable defaults true; false gates the audio bundle (#87)", async () => {
    expect((await port().capabilities()).audioAvailable).toBe(true);
    expect(
      (await port({ audioAvailable: false }).capabilities()).audioAvailable,
    ).toBe(false);
  });
});

describe("destination + reveal", () => {
  it("chooseDestination resolves a directory; reveal is honest false", async () => {
    const p: ExportPort = port({ defaultDestination: "C:\\Users\\me\\Documents" });
    await expect(p.chooseDestination()).resolves.toBe(
      "C:\\Users\\me\\Documents",
    );
    await expect(p.chooseDestination("E:\\picked")).resolves.toBe("E:\\picked");
    await expect(p.revealInExplorer("C:\\out")).resolves.toBe(false);
  });
});

describe("exportErrorCode", () => {
  it("collapses unknown throws to EXPORT_FAILED", () => {
    expect(exportErrorCode(new Error("boom"))).toBe("EXPORT_FAILED");
    expect(exportErrorCode("nope")).toBe("EXPORT_FAILED");
    expect(
      exportErrorCode(new ExportError("PERMISSION_DENIED", "x")),
    ).toBe("PERMISSION_DENIED");
  });
});

/**
 * MockExportPort — in-process emulation of the export backend so the §17
 * flow (formats, MuseScore gating, destination, progress, done/error
 * recovery) is exercisable in `vite dev` and vitest without a real engine.
 *
 * The fake reports an engine identity honestly labelled "(mock)" — the
 * diagnostics surface never pretends a real engine answered.
 *
 * Dev overrides (browser only, read once at construction):
 *   localStorage["hornscribe.dev.museScore"] === "missing"  → MuseScore
 *     reports missing so the PDF-disabled recovery path is reviewable;
 *   localStorage["hornscribe.dev.exportFailure"] in
 *     {"permission","engine","musescore","failed"}          → export()
 *     always rejects with the matching ExportError code so the error
 *     phases are reachable from the UI.
 */

import {
  withPathOverride,
  type EngineInfo,
  type ToolInfo,
  type ToolPathOverrides,
} from "../diagnostics/types";
import {
  ExportError,
  EXPORT_FORMAT_IDS,
  type ExportCapabilities,
  type ExportErrorCode,
  type ExportFormatId,
  type ExportPort,
  type ExportRequest,
  type ExportResult,
} from "./types";
import type { ExportedFile } from "./types";

/** ENG-001 filename policy: `<basename>_<artifact>`. */
const ARTIFACT_NAMES: Record<ExportFormatId, string> = {
  concertMusicxml: "concert.musicxml",
  hornMusicxml: "horn_in_f.musicxml",
  concertPdf: "concert.pdf",
  hornPdf: "horn_in_f.pdf",
  playbackMidi: "playback.mid",
  sourceAudio: "source.wav",
};

const MOCK_ENGINE: EngineInfo = {
  name: "hornscribe-engine (mock)",
  version: "0.1.0",
  python: "3.12.x",
  platform: "win32",
};

const DEV_MUSESCORE_KEY = "hornscribe.dev.museScore";
const DEV_FAILURE_KEY = "hornscribe.dev.exportFailure";

const DEV_FAILURE_CODES: Record<string, ExportErrorCode> = {
  permission: "PERMISSION_DENIED",
  engine: "ENGINE_UNAVAILABLE",
  musescore: "MUSESCORE_UNAVAILABLE",
  renderFailed: "EXPORT_MUSESCORE_RENDER_FAILED",
  diskFull: "EXPORT_DISK_FULL",
  destinationInvalid: "EXPORT_DESTINATION_INVALID",
  sourceMissing: "EXPORT_SOURCE_MISSING",
  writeFailed: "EXPORT_WRITE_FAILED",
  commitFailed: "EXPORT_COMMIT_FAILED",
  nameExhausted: "EXPORT_NAME_EXHAUSTED",
  nameInvalid: "EXPORT_NAME_INVALID",
  internal: "EXPORT_INTERNAL",
  failed: "EXPORT_FAILED",
};

export interface MockExportPortOptions {
  museScore?: ToolInfo;
  ffmpeg?: ToolInfo;
  /** Simulated audioAvailable capability (#87) — default true. */
  audioAvailable?: boolean;
  /** Simulated latency for capabilities()/export(). */
  latencyMs?: number;
  /** Deterministic failure for export() — recovery-path tests. */
  failure?: ExportErrorCode;
  defaultDestination?: string;
}

export class MockExportPort implements ExportPort {
  private readonly options: Required<
    Pick<MockExportPortOptions, "latencyMs" | "defaultDestination">
  > &
    MockExportPortOptions;

  constructor(options: MockExportPortOptions = {}) {
    this.options = { latencyMs: 450, defaultDestination: "", ...options };
  }

  /** Browser-dev factory: honours the localStorage dev flags above. */
  static withDevOverrides(): MockExportPort {
    let museScore: ToolInfo | undefined;
    let failure: ExportErrorCode | undefined;
    try {
      if (window.localStorage.getItem(DEV_MUSESCORE_KEY) === "missing") {
        museScore = { status: "missing" };
      }
      const f = window.localStorage.getItem(DEV_FAILURE_KEY);
      if (f && f in DEV_FAILURE_CODES) failure = DEV_FAILURE_CODES[f];
    } catch {
      /* localStorage may be unavailable — defaults are fine */
    }
    return new MockExportPort({ museScore, failure });
  }

  private delay(): Promise<void> {
    return new Promise((r) => setTimeout(r, this.options.latencyMs));
  }

  async capabilities(
    overrides?: ToolPathOverrides,
  ): Promise<ExportCapabilities> {
    await this.delay();
    const museScore =
      this.options.museScore ??
      ({
        status: "found",
        path: "C:\\Program Files\\MuseScore 4\\bin\\MuseScore4.exe",
        version: "4.x",
      } satisfies ToolInfo);
    const ffmpeg =
      this.options.ffmpeg ??
      ({
        status: "found",
        path: "C:\\tools\\ffmpeg\\bin\\ffmpeg.exe",
        version: "7.x",
      } satisfies ToolInfo);
    return {
      engineInfo: MOCK_ENGINE,
      protocolVersion: 1,
      backend: "basic-pitch (mock)",
      museScore: withPathOverride(museScore, overrides?.museScorePath),
      ffmpeg: withPathOverride(ffmpeg, overrides?.ffmpegPath),
      audioAvailable: this.options.audioAvailable ?? true,
    };
  }

  async chooseDestination(current?: string): Promise<string | null> {
    await this.delay();
    // A browser has no native picker — the mock "chooses" deterministically
    // so the destination row exercises the populated state.
    return current ?? (this.options.defaultDestination || this.fallbackDir());
  }

  async defaultDestination(): Promise<string> {
    return this.options.defaultDestination || this.fallbackDir();
  }

  private fallbackDir(): string {
    return "C:\\Users\\user\\Documents\\HornScribe";
  }

  async export(
    request: ExportRequest,
    signal?: AbortSignal,
  ): Promise<ExportResult> {
    await this.delay();
    // #383: honour the same cancel surface as the real port —
    // dev/testing sees the aborted run, not a silent completion.
    if (signal?.aborted) {
      throw new ExportError("EXPORT_CANCELLED", "export cancelled");
    }
    const failure = this.options.failure;
    if (failure) {
      throw new ExportError(failure, `mock export failure: ${failure}`);
    }
    if (request.formats.length === 0) {
      throw new ExportError("EXPORT_FAILED", "no formats selected");
    }
    const basename = request.basename?.trim() || "score";
    const dir = request.destination;
    const files: ExportedFile[] = EXPORT_FORMAT_IDS.filter((f) =>
      request.formats.includes(f),
    ).map((format) => {
      const artifact = ARTIFACT_NAMES[format];
      const name = `${basename}_${artifact}`;
      return { format, name, path: `${dir}\\${name}` };
    });
    return { destination: dir, files };
  }

  async revealInExplorer(): Promise<boolean> {
    // No OS bridge in a browser — honest false; the dialog announces it.
    return false;
  }

  /** §13 高度編集: the mock honours the same MuseScore-missing dev flag
   *  so the recovery announce is reviewable in `vite dev`; otherwise it
   *  resolves a fake staged path (no GUI exists in a browser). */
  async openInMuseScore(): Promise<string> {
    await this.delay();
    const missing =
      this.options.museScore != null &&
      this.options.museScore.status !== "found";
    if (missing) {
      throw new ExportError(
        "MUSESCORE_UNAVAILABLE",
        "MuseScore not found (mock)",
      );
    }
    return "C:\\Temp\\hornscribe-open-mock.musicxml";
  }
}

// @vitest-environment jsdom
/**
 * TauriExportPort flow tests (#231/#258) — the Tauri invoke boundary is
 * mocked so the collision prompt and the transactional export_run call
 * are asserted as contracts, not side effects.
 */
import { beforeEach, describe, expect, it, vi } from "vitest";
import { TauriExportPort } from "./tauriPort";
import { createFixtureScoreDocument } from "../score/fixtureDocument";

const invokeMock = vi.fn();
vi.mock("@tauri-apps/api/core", () => ({
  invoke: (...args: unknown[]) => invokeMock(...args),
}));

function source() {
  return {
    doc: createFixtureScoreDocument(),
    basename: "take1",
    audioPath: "C:\\audio\\take.wav",
    audioName: "take.wav",
  };
}

function port() {
  return new TauriExportPort(source);
}

describe("TauriExportPort.export", () => {
  beforeEach(() => {
    invokeMock.mockReset();
    invokeMock.mockImplementation(async (cmd: string) => {
      if (cmd === "export_check_existing") return [];
      if (cmd === "export_run") {
        return [
          "C:\\out\\take1_source.wav",
          "C:\\out\\take1_concert.musicxml",
        ];
      }
      if (cmd === "detect_tools") {
        return { museScore: { status: "missing" }, ffmpeg: { status: "missing" } };
      }
      throw new Error("unexpected invoke " + cmd);
    });
  });

  it("writes through one transactional export_run call", async () => {
    const res = await port().export({
      formats: ["concertMusicxml", "sourceAudio"],
      destination: "C:\\out",
      basename: "take1",
    });
    const run = invokeMock.mock.calls.find((c) => c[0] === "export_run");
    expect(run).toBeTruthy();
    expect(run?.[1]).toMatchObject({
      dir: "C:\\out",
      audio: { name: "take1_source.wav", src: "C:\\audio\\take.wav" },
      musescorePath: null,
    });
    expect(res.files.map((f) => f.name)).toEqual([
      "take1_concert.musicxml",
      "take1_source.wav",
    ]);
  });

  it("asks onCollision once when names already exist (#231)", async () => {
    invokeMock.mockImplementation(async (cmd: string) => {
      if (cmd === "export_check_existing") {
        return ["take1_concert.musicxml"];
      }
      if (cmd === "export_run") return ["C:\\out\\take1_concert.musicxml"];
      throw new Error("unexpected " + cmd);
    });
    const seen: string[][] = [];
    await port().export({
      formats: ["concertMusicxml"],
      destination: "C:\\out",
      basename: "take1",
      onCollision: async (names) => {
        seen.push([...names]);
        return "overwrite";
      },
    });
    expect(seen).toEqual([["take1_concert.musicxml"]]);
    expect(invokeMock.mock.calls.some((c) => c[0] === "export_run")).toBe(true);
  });

  it("rename re-stems the whole set until the check is clear (#231)", async () => {
    const checks: string[][] = [];
    invokeMock.mockImplementation(async (cmd: string, args: { names?: string[] }) => {
      if (cmd === "export_check_existing") {
        checks.push([...(args.names ?? [])]);
        return args.names?.every((n) => n.startsWith("take1_2_")) ? [] : [args.names?.[0]];
      }
      if (cmd === "export_run") return ["C:\\out\\take1_2_concert.musicxml"];
      throw new Error("unexpected " + cmd);
    });
    const res = await port().export({
      formats: ["concertMusicxml"],
      destination: "C:\\out",
      basename: "take1",
      onCollision: async () => "rename",
    });
    expect(res.files[0].name).toBe("take1_2_concert.musicxml");
    expect(checks.length).toBeGreaterThanOrEqual(2);
  });

  it("cancel surfaces EXPORT_CANCELLED and never runs (#231)", async () => {
    invokeMock.mockImplementation(async (cmd: string) => {
      if (cmd === "export_check_existing") return ["take1_concert.musicxml"];
      if (cmd === "export_run") throw new Error("must not run");
      throw new Error("unexpected " + cmd);
    });
    await expect(
      port().export({
        formats: ["concertMusicxml"],
        destination: "C:\\out",
        basename: "take1",
        onCollision: async () => "cancel",
      }),
    ).rejects.toMatchObject({ code: "EXPORT_CANCELLED" });
    expect(invokeMock.mock.calls.some((c) => c[0] === "export_run")).toBe(false);
  });

  it("PDF without MuseScore fails before export_run (#258)", async () => {
    await expect(
      port().export({
        formats: ["concertPdf"],
        destination: "C:\\out",
      }),
    ).rejects.toMatchObject({ code: "MUSESCORE_UNAVAILABLE" });
    expect(invokeMock.mock.calls.some((c) => c[0] === "export_run")).toBe(false);
  });

  it("abort during the run fires export_cancel with the matching exportId (#383)", async () => {
    let runId = "";
    invokeMock.mockImplementation(async (cmd: string, args: unknown) => {
      if (cmd === "export_check_existing") return [];
      if (cmd === "export_run") {
        runId = (args as { exportId: string }).exportId;
        // The Rust side notices the flag and rejects cancelled —
        // simulate the same outcome the real command produces.
        await new Promise((r) => setTimeout(r, 20));
        throw new Error("EXPORT_CANCELLED");
      }
      if (cmd === "export_cancel") return null;
      throw new Error("unexpected " + cmd);
    });
    const controller = new AbortController();
    const pending = port().export(
      { formats: ["concertMusicxml"], destination: "C:\\out" },
      controller.signal,
    );
    // Wait until the transactional call is actually in flight.
    for (let i = 0; i < 100 && !runId; i++) {
      await new Promise((r) => setTimeout(r, 0));
    }
    controller.abort();
    await expect(pending).rejects.toMatchObject({
      code: "EXPORT_CANCELLED",
    });
    const cancel = invokeMock.mock.calls.find((c) => c[0] === "export_cancel");
    expect(runId).not.toBe("");
    expect(cancel?.[1]).toEqual({ exportId: runId });
  });

  it("a pre-aborted signal rejects EXPORT_CANCELLED without the bridge (#383)", async () => {
    const controller = new AbortController();
    controller.abort();
    await expect(
      port().export(
        { formats: ["concertMusicxml"], destination: "C:\\out" },
        controller.signal,
      ),
    ).rejects.toMatchObject({ code: "EXPORT_CANCELLED" });
    expect(invokeMock.mock.calls.some((c) => c[0] === "export_run")).toBe(
      false,
    );
  });

  // #384: the Rust side tags every failure `CODE: detail` — the
  // prefix alone selects the recovery surface; untagged errors still
  // collapse to EXPORT_FAILED.
  it.each([
    ["EXPORT_DISK_FULL: write C:\\out\\take.mid: os error 112", "EXPORT_DISK_FULL"],
    ["EXPORT_SOURCE_MISSING: C:\\audio\\take.wav", "EXPORT_SOURCE_MISSING"],
    ["EXPORT_MUSESCORE_RENDER_FAILED: MuseScore exited with exit code: 1", "EXPORT_MUSESCORE_RENDER_FAILED"],
    ["EXPORT_DESTINATION_INVALID: not a directory: C:\\x", "EXPORT_DESTINATION_INVALID"],
    ["EXPORT_COMMIT_FAILED: write C:\\out\\take.mid: os error 5", "EXPORT_COMMIT_FAILED"],
    ["EXPORT_WRITE_FAILED: stage C:\\tmp\\h: os error 123", "EXPORT_WRITE_FAILED"],
    ["EXPORT_NAME_INVALID: ../evil", "EXPORT_NAME_INVALID"],
    ["EXPORT_INTERNAL: take.mid: bad base64 byte", "EXPORT_INTERNAL"],
    ["PERMISSION_DENIED", "PERMISSION_DENIED"],
    ["PERMISSION_DENIED: create C:\\out: os error 5", "PERMISSION_DENIED"],
    ["write C:\\out\\take.mid: os error 1", "EXPORT_FAILED"],
    ["MuseScore exited with exit code: 1", "EXPORT_FAILED"],
  ])("export_run rejection %j maps to %s", async (message, code) => {
    invokeMock.mockImplementation(async (cmd: string) => {
      if (cmd === "export_check_existing") return [];
      if (cmd === "export_run") throw new Error(message);
      throw new Error("unexpected " + cmd);
    });
    await expect(
      port().export({
        formats: ["concertMusicxml"],
        destination: "C:\\out",
      }),
    ).rejects.toMatchObject({ code });
  });
});

