/**
 * TauriExportPort — the real export backend inside the Tauri webview
 * (#99). MusicXML and MIDI are produced entirely client-side from the
 * live score document (user edits included via musicXml(view)); PDF
 * renders through a detected MuseScore install. No engine process is
 * required for any format.
 *
 * Rust commands (src-tauri/src/export.rs) own the privileged halves:
 * folder picking, artifact writes (granted-dir allowlist), tool
 * probing, explorer reveal and the MuseScore subprocess.
 */
import { invoke } from "@tauri-apps/api/core";
import {
  type ToolPathOverrides,
} from "../diagnostics/types";
import {
  detectTools,
  resolveToolWithOverride,
} from "../diagnostics/toolProbe";
import type { ScoreDocumentPort } from "../score/document";
import { buildMidiFile } from "./midi";
import {
  ExportError,
  type ExportCapabilities,
  type ExportErrorCode,
  type ExportFormatId,
  type ExportPort,
  type ExportRequest,
  type ExportResult,
  type ExportedFile,
} from "./types";

/** ENG-001 filename policy shared with the mock port. */
const ARTIFACT_NAMES: Record<ExportFormatId, string> = {
  concertMusicxml: "concert.musicxml",
  hornMusicxml: "horn_in_f.musicxml",
  concertPdf: "concert.pdf",
  hornPdf: "horn_in_f.pdf",
  playbackMidi: "playback.mid",
  // The real artifact keeps the source's own extension — this is only
  // the display-name fallback when the copy result has no file name.
  sourceAudio: "source.wav",
};

/** What the port needs from the app at export time. */
export interface ExportSource {
  /** Live score document (XML bodies + meta); null = nothing to export. */
  readonly doc: ScoreDocumentPort | null;
  /** Default file basename — audio file stem or score title. */
  readonly basename: string;
  /** Absolute path of the loaded audio when it lives on disk — enables
   *  the sourceAudio bundle format (#87). Null for browser-held bytes. */
   readonly audioPath: string | null;
  /** Original audio file name (extension kept) for the bundle copy. */
   readonly audioName: string | null;
}

/** UTF-8-safe base64 (btoa chokes on multibyte; chunk to stay under the
 *  String.fromCharCode arg limit). */
function toBase64(bytes: Uint8Array): string {
  let bin = "";
  const CHUNK = 0x8000;
  for (let i = 0; i < bytes.length; i += CHUNK) {
    bin += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
  }
  return btoa(bin);
}

function textToBase64(text: string): string {
  return toBase64(new TextEncoder().encode(text));
}

/** Filesystem-safe basename: strip separators and illegal chars. */
function sanitizeBasename(raw: string): string {
  const cleaned = raw
    .replace(/[\\/:*?"<>|]/g, "_")
    .replace(/\.+$/, "")
    .trim();
  return cleaned || "score";
}

/** Mirror of the Rust-side audio stem sanitize (export_copy_audio):
 *  path/illegal chars AND dots become underscores so the predicted
 *  `<stem>_source.<ext>` name matches what export_run writes. */
function sanitizeAudioStem(raw: string): string {
  const cleaned = raw
    .replace(/[\\/:*?"<>|.]/g, "_")
    .trim();
  return cleaned || "audio";
}

/** Audio file extension (lowercased) for the bundle copy name. */
function audioExtOf(name: string | null): string {
  const m = /\.([A-Za-z0-9]+)$/.exec(name ?? "");
  return m ? m[1].toLowerCase() : "wav";
}

function mapInvokeError(err: unknown): ExportError {
  const msg = err instanceof Error ? err.message : String(err);
  // #384: Rust errors arrive as `CODE` or `CODE: detail` — the token
  // before the first colon is the stable UI-facing code; anything
  // after stays in the message for diagnostics and never reaches the
  // dialog. Unknown/untagged failures collapse to EXPORT_FAILED.
  const head = msg.trimStart().split(":", 1)[0]?.trim() ?? "";
  const code = INVOKE_ERROR_CODES.find((c) => c === head);
  return new ExportError(code ?? "EXPORT_FAILED", msg);
}

/** Codes the Rust export commands may emit — prefix-matched by
 *  mapInvokeError (#384). */
const INVOKE_ERROR_CODES: readonly ExportErrorCode[] = [
  "PERMISSION_DENIED",
  "ENGINE_UNAVAILABLE",
  "MUSESCORE_UNAVAILABLE",
  "EXPORT_DISK_FULL",
  "EXPORT_SOURCE_MISSING",
  "EXPORT_MUSESCORE_RENDER_FAILED",
  "EXPORT_DESTINATION_INVALID",
  "EXPORT_WRITE_FAILED",
  "EXPORT_COMMIT_FAILED",
  "EXPORT_NAME_INVALID",
  "EXPORT_NAME_EXHAUSTED",
  "EXPORT_INTERNAL",
  "EXPORT_CANCELLED",
  "EXPORT_FAILED",
];

export class TauriExportPort implements ExportPort {
  /** Last tool-path overrides seen by capabilities() — reused by the
   *  PDF branch of export() so a user-specified MuseScore path wins. */
  private overrides?: ToolPathOverrides;

  /** #256: canonical MIDI via the engine's playback_midi_bytes — keeps
   *  velocity / pitch bend / swing / tempo map. When absent (or the
   *  document has no canonical payload) the client-side MusicXML→MIDI
   *  rebuild is used as before. */
  private readonly midiExporter?: (scoreDocument: unknown) => Promise<string>;

  /** Monotonic id source for `export_run`/`export_cancel` pairing —
   *  collision-safe per export attempt (#383). */
  private exportSeq = 0;

  constructor(
    private readonly source: () => ExportSource | null,
    midiExporter?: (scoreDocument: unknown) => Promise<string>,
  ) {
    this.midiExporter = midiExporter;
  }

  async capabilities(
    overrides?: ToolPathOverrides,
  ): Promise<ExportCapabilities> {
    this.overrides = overrides;
    const tools = await detectTools();
    // #363: a user-set override is probed against the filesystem — a
    // bad path reports missing (with the path kept) instead of a blind
    // 検出済み that only fails at export time.
    const [museScore, ffmpeg] = await Promise.all([
      resolveToolWithOverride(
        tools?.museScore ?? { status: "missing" },
        overrides?.museScorePath,
      ),
      resolveToolWithOverride(
        tools?.ffmpeg ?? { status: "missing" },
        overrides?.ffmpegPath,
      ),
    ]);
    return {
      // Client-side export needs no engine — report that honestly
      // rather than faking a handshake.
      engineInfo: null,
      protocolVersion: null,
      backend: null,
      museScore,
      ffmpeg,
      audioAvailable: this.source()?.audioPath != null,
    };
  }

  async chooseDestination(current?: string): Promise<string | null> {
    try {
      return await invoke<string | null>("export_pick_dir", {
        current: current ?? null,
      });
    } catch (err) {
      throw mapInvokeError(err);
    }
  }

  async defaultDestination(): Promise<string> {
    try {
      return await invoke<string>("export_default_dir");
    } catch (err) {
      throw mapInvokeError(err);
    }
  }

  async export(
    request: ExportRequest,
    signal?: AbortSignal,
  ): Promise<ExportResult> {
    // #383: a cancelled run throws EXPORT_CANCELLED — the dialog treats
    // it as a quiet abort, never an error surface.
    const throwIfAborted = () => {
      if (signal?.aborted) {
        throw new ExportError("EXPORT_CANCELLED", "export cancelled");
      }
    };
    throwIfAborted();
    const source = this.source();
    if (!source?.doc) {
      // #384: a missing document is a client-side precondition bug —
      // the dialog offers retry/diagnostics, not destination advice.
      throw new ExportError("EXPORT_INTERNAL", "no score document to export");
    }
    const basename = sanitizeBasename(
      request.basename?.trim() || source.basename || source.doc.meta.title,
    );
    const dir = request.destination;
    const files: ExportedFile[] = [];
    // Plan every artifact up front: names are needed for the
    // collision check (#231) before anything is staged (#258).
    const wantsAudio =
      request.formats.includes("sourceAudio") && source.audioPath != null;
    const pdfFormats = request.formats.filter(
      (f) => f === "concertPdf" || f === "hornPdf",
    );
    const plan = (stem: string) => {
      const names = new Map<ExportFormatId, string>();
      for (const format of request.formats) {
        if (format === "sourceAudio") {
          if (wantsAudio) {
            names.set(
              format,
              `${sanitizeAudioStem(stem)}_source.${audioExtOf(source.audioName)}`,
            );
          }
        } else {
          names.set(format, `${stem}_${ARTIFACT_NAMES[format]}`);
        }
      }
      return names;
    };

    // #231: never overwrite silently — ask once for the whole set.
    let stem = basename;
    let names = plan(stem);
    let existing = await invoke<string[]>("export_check_existing", {
      dir,
      names: [...names.values()],
    }).catch((err) => {
      throw mapInvokeError(err);
    });
    if (existing.length > 0 && request.onCollision) {
      const policy = await request.onCollision(existing);
      if (policy === "cancel") {
        throw new ExportError("EXPORT_CANCELLED", "export cancelled");
      }
      if (policy === "rename") {
        // Re-stem the whole set — every artifact of one export shares
        // one basename, so a suffix keeps the bundle coherent.
        for (let n = 2; n <= 999 && existing.length > 0; n++) {
          stem = `${basename}_${n}`;
          names = plan(stem);
          existing = await invoke<string[]>("export_check_existing", {
            dir,
            names: [...names.values()],
          }).catch((err) => {
            throw mapInvokeError(err);
          });
        }
        if (existing.length > 0) {
          // Pathological: 999 stems taken — refuse rather than
          // silently overwriting after the user chose rename.
          throw new ExportError("EXPORT_NAME_EXHAUSTED", "no free export name");
        }
      }
    }

    // Resolve MuseScore before staging anything — a missing tool must
    // fail before the transaction, not inside it (#258).
    let museScorePath: string | null = null;
    if (pdfFormats.length > 0) {
      const caps = await this.capabilities(this.overrides);
      museScorePath =
        caps.museScore.status === "found" ? (caps.museScore.path ?? null) : null;
      if (!museScorePath) {
        throw new ExportError(
          "MUSESCORE_UNAVAILABLE",
          "MuseScore not found; PDF export is unavailable",
        );
      }
    }

    // Build payloads: text/binary artifacts go base64; PDFs carry
    // their MusicXML source for the staged render; audio is a path
    // copy (no base64 round-trip for what can be a large file).
    const batch: { name: string; dataBase64: string }[] = [];
    const pdfPayloads: { name: string; musicXml: string }[] = [];
    for (const format of request.formats) {
      const name = names.get(format);
      if (!name) continue;
      if (format === "concertMusicxml") {
        batch.push({ name, dataBase64: textToBase64(source.doc.musicXml("concert")) });
      } else if (format === "hornMusicxml") {
        batch.push({ name, dataBase64: textToBase64(source.doc.musicXml("hornF")) });
      } else if (format === "playbackMidi") {
        // #256: prefer the engine's canonical exporter — it carries
        // velocity / pitch bend / swing / tempo map the MusicXML
        // rebuild loses. Falls back to the client-side build only
        // when no canonical payload or no engine hook exists.
        const canonical = source.doc.canonicalDocument?.();
        if (canonical && this.midiExporter) {
          let midiBase64: string;
          try {
            midiBase64 = await this.midiExporter(canonical);
          } catch (err) {
            const msg = err instanceof Error ? err.message : String(err);
            throw new ExportError("EXPORT_FAILED", msg);
          }
          batch.push({ name, dataBase64: midiBase64 });
        } else {
          batch.push({
            name,
            dataBase64: toBase64(buildMidiFile(source.doc.musicXml("concert"))),
          });
        }
      } else if (format === "concertPdf" || format === "hornPdf") {
        pdfPayloads.push({
          name,
          musicXml: source.doc.musicXml(format === "hornPdf" ? "hornF" : "concert"),
        });
      }
    }

    // #258: one transactional call — audio + files + PDFs are staged
    // and committed together; a failure anywhere writes nothing.
    // #383: the run is cancellable end-to-end — exportId pairs with
    // export_cancel, which flips the Rust-side flag and kills the
    // MuseScore child; staging then tears down without committing.
    const exportId = `hornscribe-export-${Date.now()}-${++this.exportSeq}`;
    const onAbort = () => {
      void invoke("export_cancel", { exportId }).catch(() => undefined);
    };
    signal?.addEventListener("abort", onAbort, { once: true });
    let paths: string[];
    try {
      throwIfAborted();
      paths = await invoke<string[]>("export_run", {
        dir,
        audio: wantsAudio
          ? { name: names.get("sourceAudio"), src: source.audioPath }
          : null,
        files: batch,
        pdfs: pdfPayloads,
        musescorePath: museScorePath,
        exportId,
      }).catch((err) => {
        throw mapInvokeError(err);
      });
    } finally {
      signal?.removeEventListener("abort", onAbort);
    }

    // export_run returns staged-commit order: audio, files, then PDFs —
    // map back onto formats by name for the result list.
    const byName = new Map(paths.map((p) => [p.split(/[\\/]/).pop() ?? "", p]));
    for (const format of request.formats) {
      const name = names.get(format);
      if (!name) continue;
      files.push({
        format,
        name,
        path: byName.get(name) ?? `${dir}\\${name}`,
      });
    }
    return { destination: dir, files };
  }

  async revealInExplorer(path: string): Promise<boolean> {
    try {
      await invoke("reveal_in_explorer", { path });
      return true;
    } catch {
      return false;
    }
  }

  /** §13 高度編集: hand the live score to the MuseScore GUI. The view
   *  argument picks concert vs F管 written pitch — the same document the
   *  user is looking at, edits included. */
  async openInMuseScore(
    view: "concert" | "hornF",
    overrides?: ToolPathOverrides,
  ): Promise<string> {
    const source = this.source();
    if (!source?.doc) {
      throw new ExportError("EXPORT_INTERNAL", "no score document to open");
    }
    const caps = await this.capabilities(overrides ?? this.overrides);
    const exe = caps.museScore.status === "found" ? caps.museScore.path : null;
    if (!exe) {
      throw new ExportError(
        "MUSESCORE_UNAVAILABLE",
        "MuseScore not found; set its path in 設定 → ツール",
      );
    }
    try {
      return await invoke<string>("open_in_musescore", {
        musescorePath: exe,
        musicXml: source.doc.musicXml(view),
        basename: source.basename || source.doc.meta.title,
      });
    } catch (err) {
      throw mapInvokeError(err);
    }
  }
}

/**
 * Export contract types (UI-060; GUI_UX_SPEC §17; ENG-001 semantics).
 *
 * The dialog talks to a typed {@link ExportPort} (port.ts) — the same
 * port/gate layering the sidecar client uses (`src/sidecar/port.ts` in
 * UI-040): a mock port makes the whole UX exercisable in a plain browser,
 * while a real engine reports the same capability surface through the
 * `engine.handshake` response once the spawn bridge lands.
 */

import type {
  EngineInfo,
  ToolInfo,
  ToolPathOverrides,
} from "../diagnostics/types";

/**
 * The five export choices of §17. ENG-001 semantics:
 * - `concertMusicxml` / `hornMusicxml` → `*_concert.musicxml` /
 *   `*_horn_in_f.musicxml`; the F管ホルン artifact carries written pitches
 *   plus the -P5 `<transpose>` element so readers recover sounding pitch;
 * - `playbackMidi` → `*_playback.mid`, always *sounding* (concert) pitch —
 *   SMF has no transposing-instrument semantics, so a written-pitch MIDI
 *   would be ambiguous about its own pitch space (再生用MIDIは実音);
 * - `concertPdf` / `hornPdf` → rendered through MuseScore, hence gated by
 *   the MuseScore tool capability.
 * - `sourceAudio` → the original audio file copied alongside the score
 *   artifacts (#87 成果物同梱): a recording→score bundle stays usable
 *   outside the app. Gated by `capabilities.audioAvailable` — only refs
 *   backed by a real path can be copied.
 */
export type ExportFormatId =
  | "concertMusicxml"
  | "hornMusicxml"
  | "concertPdf"
  | "hornPdf"
  | "playbackMidi"
  | "sourceAudio";

/** Checkbox grouping from the spec mock-up (楽譜 / PDF / MIDI / 音声). */
export type ExportFormatGroup = "score" | "pdf" | "midi" | "audio";

export const EXPORT_FORMAT_GROUPS: Record<ExportFormatId, ExportFormatGroup> = {
  concertMusicxml: "score",
  hornMusicxml: "score",
  concertPdf: "pdf",
  hornPdf: "pdf",
  playbackMidi: "midi",
  sourceAudio: "audio",
};

export const EXPORT_FORMAT_IDS: readonly ExportFormatId[] = [
  "concertMusicxml",
  "hornMusicxml",
  "concertPdf",
  "hornPdf",
  "playbackMidi",
  "sourceAudio",
];

/**
 * The capability surface the export dialog needs — a subset of the engine
 * handshake plus local tool detection (MuseScore drives PDF availability;
 * FFmpeg is reported for consistency with diagnostics).
 */
export interface ExportCapabilities {
  readonly engineInfo: EngineInfo | null;
  readonly protocolVersion: number | null;
  /** Transcription backend id when known (diagnostics parity). */
  readonly backend: string | null;
  readonly museScore: ToolInfo;
  readonly ffmpeg: ToolInfo;
  /** True when the loaded audio is backed by a real path and can be
   *  copied into the export bundle (sourceAudio format, #87). */
  readonly audioAvailable: boolean;
}

/** PDF export requires MuseScore; everything else stays available (§17). */
export function pdfBlocked(capabilities: ExportCapabilities): boolean {
  return capabilities.museScore.status !== "found";
}

/** A single written artifact returned by a successful export. */
export interface ExportedFile {
  readonly format: ExportFormatId;
  /** Absolute path of the written file. */
  readonly path: string;
  /** File name only (for display). */
  readonly name: string;
}

export interface ExportRequest {
  /** Formats to write — at least one, all enabled by capabilities. */
  readonly formats: readonly ExportFormatId[];
  /** Destination directory (absolute path). */
  readonly destination: string;
  /** Document base name for `<basename>_<artifact>` naming (ENG-001). */
  readonly basename?: string;
  /** #231: called once before writing when target names already
   *  exist — the host decides the collision policy for the whole set.
   *  "rename" re-stems every artifact to <basename>_N; "cancel"
   *  aborts the export with an EXPORT_CANCELLED result-free rejection.
   *  Absent = overwrite (non-interactive ports, tests). */
  readonly onCollision?: (
    existingNames: readonly string[],
  ) => Promise<"overwrite" | "rename" | "cancel">;
}

export interface ExportResult {
  readonly destination: string;
  readonly files: readonly ExportedFile[];
}

/**
 * Stable error codes the UI maps onto Japanese recovery copy — raw engine
 * messages and stack traces never reach the dialog (§20, acceptance:
 * "technical stack trace is not shown in normal error UI").
 */
export type ExportErrorCode =
  /** Destination is not writable (permission / read-only). */
  | "PERMISSION_DENIED"
  /** No engine connected (sidecar not spawned / crashed). */
  | "ENGINE_UNAVAILABLE"
  /** PDF was requested without a usable MuseScore. */
  | "MUSESCORE_UNAVAILABLE"
  /** No space left on the staging or destination device. */
  | "EXPORT_DISK_FULL"
  /** The source-audio file for the bundle vanished/moved. */
  | "EXPORT_SOURCE_MISSING"
  /** MuseScore ran (or failed to spawn) but the render did not
   *  succeed — distinct from the binary being absent. */
  | "EXPORT_MUSESCORE_RENDER_FAILED"
  /** Destination path does not exist or is not a usable directory. */
  | "EXPORT_DESTINATION_INVALID"
  /** A staged write/copy failed for a non-permission, non-space
   *  reason — nothing reached the destination. */
  | "EXPORT_WRITE_FAILED"
  /** The commit loop failed mid-way — a partial artifact set may
   *  exist in the destination (the dialog says so honestly). */
  | "EXPORT_COMMIT_FAILED"
  /** An artifact name failed Rust-side validation — a client-side
   *  generation bug, not something the user can fix. */
  | "EXPORT_NAME_INVALID"
  /** The rename loop found no free stem (999 collisions). */
  | "EXPORT_NAME_EXHAUSTED"
  /** Client-side/precondition failure (bad payload, no document). */
  | "EXPORT_INTERNAL"
  /** Anything else — generic failure with retry/diagnostics. */
  | "EXPORT_FAILED"
  /** #231: the user cancelled at the collision prompt — resolved
   *  quietly, not an error surface. */
  | "EXPORT_CANCELLED";

export class ExportError extends Error {
  readonly code: ExportErrorCode;
  constructor(code: ExportErrorCode, message: string) {
    super(message);
    this.name = "ExportError";
    this.code = code;
  }
}

/** Maps an unknown thrown value to a stable code for the dialog. */
export function exportErrorCode(err: unknown): ExportErrorCode {
  if (err instanceof ExportError) return err.code;
  return "EXPORT_FAILED";
}

/**
 * ExportPort — the seam between the 書き出し dialog and a concrete export
 * backend (see port.ts for the runtime gate). Declared here with the rest
 * of the contract so implementations never import the port module itself.
 */
export interface ExportPort {
  /**
   * Probe export-relevant capabilities: engine identity, protocol version,
   * backend and tool detection. `overrides` carries the user-specified tool
   * paths from 設定 → ツール/書き出し (non-empty paths win over probing).
   * Rejects with ExportError(ENGINE_UNAVAILABLE) when no engine/backend
   * can answer — the dialog shows the recovery surface, not a crash.
   */
  capabilities(overrides?: ToolPathOverrides): Promise<ExportCapabilities>;
  /**
   * Ask the user for a destination directory (native picker where a real
   * bridge exists). Resolves null when the picker was cancelled.
   */
  chooseDestination(current?: string): Promise<string | null>;
  /**
   * The directory preselected in the dialog: the 設定 → 書き出し default
   * when set, else the engine/OS documents location.
   */
  defaultDestination(): Promise<string>;
  /**
   * Run the export. Resolves with the written artifacts; rejects with a
   * typed {@link ExportError} whose code drives the §20 recovery surface —
   * raw engine output/stack traces stay behind the port.
   */
  export(request: ExportRequest, signal?: AbortSignal): Promise<ExportResult>;
  /**
   * Reveal a directory in the OS file manager (エクスプローラーで表示).
   * Resolves false where the bridge cannot do that — the caller announces
   * the failure instead of pretending.
   */
  revealInExplorer(path: string): Promise<boolean>;
  /**
   * §13 高度編集: open the live score (user edits included) in the
   * MuseScore GUI — stages the current view's MusicXML to a temp file
   * and launches the detected/user-pinned executable. Resolves the
   * staged path; rejects with ExportError(MUSESCORE_UNAVAILABLE) when
   * no MuseScore is usable. Optional so browser/mock ports and leaner
   * test doubles keep compiling — an absent implementation is a no-op.
   */
  openInMuseScore?(
    view: "concert" | "hornF",
    overrides?: ToolPathOverrides,
  ): Promise<string>;
}
